//! Watches the open paper folder so edits made elsewhere (Claude Code, Overleaf sync, a figure
//! regenerated by a script) reach the editor. Sends `project-changed` with the root-relative
//! paths; the frontend decides what each change means. Commits, pulls and checkouts made
//! elsewhere touch only `.git`, so those send `repo-changed` instead.

use notify::{Event, EventKind, RecommendedWatcher, RecursiveMode, Watcher};
use serde::Serialize;
use std::path::{Component, Path};
use std::sync::Mutex;
use tauri::{AppHandle, Emitter};

#[derive(Default)]
pub struct State(Mutex<Option<RecommendedWatcher>>);

#[derive(Clone, Serialize)]
struct Changed {
    root: String,
    paths: Vec<String>,
}

// What TeX and editors leave behind; changes to these never mean the paper changed.
const BUILD_EXTENSIONS: &[&str] = &[
    "aux", "log", "out", "fls", "fdb_latexmk", "synctex", "gz", "blg", "toc", "lof", "lot", "nav", "snm", "vrb", "xdv", "swp", "tmp",
];

/// The root-relative path of a change worth telling the editor about, or None.
pub fn relevant(root: &Path, path: &Path) -> Option<String> {
    let rel = path.strip_prefix(root).ok()?;
    let parts: Vec<String> = rel
        .components()
        .filter_map(|c| match c {
            Component::Normal(s) => Some(s.to_string_lossy().into_owned()),
            _ => None,
        })
        .collect();
    let name = parts.last()?;
    // Hidden folders (.git) are skipped, except tuhi's own .tuhi at the top.
    let hidden = parts.iter().enumerate().any(|(i, p)| p.starts_with('.') && !(i == 0 && p == ".tuhi" && parts.len() > 1));
    if hidden || parts.iter().any(|p| p == "node_modules" || p.starts_with("_minted")) {
        return None;
    }
    let ext = Path::new(name).extension().and_then(|e| e.to_str()).unwrap_or_default().to_ascii_lowercase();
    if name.ends_with('~') || name.starts_with('#') || name == "4913" || name.contains("-converted-to.") || BUILD_EXTENSIONS.contains(&ext.as_str()) {
        return None;
    }
    Some(parts.join("/"))
}

/// Whether `path` is git's index, HEAD or a ref: what changes when someone commits, pulls or
/// checks out outside tuhi. Lock files and objects are left out.
pub fn repo_state(root: &Path, path: &Path) -> bool {
    let Ok(rel) = path.strip_prefix(root.join(".git")) else { return false };
    let first = rel.components().next().map(|c| c.as_os_str().to_string_lossy().into_owned());
    let lock = path.extension().is_some_and(|e| e == "lock");
    !lock && matches!(first.as_deref(), Some("index" | "HEAD" | "packed-refs" | "refs" | "MERGE_HEAD"))
}

/// Starts watching `root`, replacing any earlier watch.
pub fn watch(app: AppHandle, state: &State, root: &Path) -> Result<(), String> {
    let mut slot = state.0.lock().map_err(|e| e.to_string())?;
    *slot = None;
    let root = root.canonicalize().map_err(|e| e.to_string())?;
    let base = root.clone();
    let mut watcher = notify::recommended_watcher(move |event: notify::Result<Event>| {
        let Ok(event) = event else { return };
        if matches!(event.kind, EventKind::Access(_)) {
            return;
        }
        if event.paths.iter().any(|p| repo_state(&base, p)) {
            let _ = app.emit("repo-changed", base.to_string_lossy().into_owned());
        }
        let paths: Vec<String> = event.paths.iter().filter_map(|p| relevant(&base, p)).collect();
        if !paths.is_empty() {
            let _ = app.emit("project-changed", Changed { root: base.to_string_lossy().into_owned(), paths });
        }
    })
    .map_err(|e| e.to_string())?;
    watcher.watch(&root, RecursiveMode::Recursive).map_err(|e| e.to_string())?;
    *slot = Some(watcher);
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn keeps_paper_and_tuhi_files_only() {
        let root = Path::new("/p");
        let rel = |p: &str| relevant(root, &root.join(p));
        assert_eq!(rel("main.tex").as_deref(), Some("main.tex"));
        assert_eq!(rel("figures/fig1.pdf").as_deref(), Some("figures/fig1.pdf"));
        assert_eq!(rel(".tuhi/suggestions.json").as_deref(), Some(".tuhi/suggestions.json"));
        assert_eq!(rel(".tuhi/reviews/r1.json").as_deref(), Some(".tuhi/reviews/r1.json"));
        assert_eq!(rel(".git/index"), None);
        assert_eq!(rel("figures/.DS_Store"), None);
        assert_eq!(rel("main.aux"), None);
        assert_eq!(rel("main.tex~"), None);
        assert_eq!(rel("fig-eps-converted-to.pdf"), None);
        assert_eq!(rel("_minted-main/x.pygtex"), None);
        assert_eq!(rel(".tuhi"), None);
    }

    #[test]
    fn sees_commits_but_not_locks_or_objects() {
        let root = Path::new("/p");
        let repo = |p: &str| repo_state(root, &root.join(p));
        assert!(repo(".git/index"));
        assert!(repo(".git/HEAD"));
        assert!(repo(".git/refs/heads/main"));
        assert!(repo(".git/packed-refs"));
        assert!(!repo(".git/index.lock"));
        assert!(!repo(".git/refs/heads/main.lock"));
        assert!(!repo(".git/objects/ab/cdef"));
        assert!(!repo(".git/FETCH_HEAD"));
        assert!(!repo("main.tex"));
    }

    /// The OS reports real paths (/private/var/… on macOS); they must still map to the project.
    #[test]
    fn sees_writes_in_a_real_folder() {
        let dir = std::env::temp_dir().join(format!("tuhi-watch-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("figures")).unwrap();
        let root = dir.canonicalize().unwrap();
        let (tx, rx) = std::sync::mpsc::channel();
        let base = root.clone();
        let mut watcher = notify::recommended_watcher(move |event: notify::Result<Event>| {
            for path in event.map(|e| e.paths).unwrap_or_default() {
                if let Some(rel) = relevant(&base, &path) {
                    let _ = tx.send(rel);
                }
            }
        })
        .unwrap();
        watcher.watch(&root, RecursiveMode::Recursive).unwrap();
        std::thread::sleep(std::time::Duration::from_millis(300));
        std::fs::write(dir.join("main.aux"), "x").unwrap();
        std::fs::write(dir.join("figures/fig.pdf"), "x").unwrap();
        let mut seen = Vec::new();
        while let Ok(rel) = rx.recv_timeout(std::time::Duration::from_secs(3)) {
            seen.push(rel);
            if seen.iter().any(|s| s == "figures/fig.pdf") {
                break;
            }
        }
        let _ = std::fs::remove_dir_all(&dir);
        assert!(seen.iter().any(|s| s == "figures/fig.pdf"), "saw {seen:?}");
        assert!(!seen.iter().any(|s| s == "main.aux"));
    }

    /// A commit made in a terminal changes only .git, and must still be seen.
    #[test]
    fn sees_a_commit_made_elsewhere() {
        let dir = std::env::temp_dir().join(format!("tuhi-watch-git-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let root = dir.canonicalize().unwrap();
        let g = |args: &[&str]| assert!(std::process::Command::new("git").arg("-C").arg(&root).args(args).output().unwrap().status.success());
        g(&["init", "-q", "-b", "main"]);
        g(&["config", "user.email", "t@example.com"]);
        g(&["config", "user.name", "T"]);
        std::fs::write(root.join("old.tex"), "x").unwrap();
        g(&["add", "old.tex"]);
        g(&["commit", "-qm", "Add old"]);
        let (tx, rx) = std::sync::mpsc::channel();
        let base = root.clone();
        let mut watcher = notify::recommended_watcher(move |event: notify::Result<Event>| {
            if event.map(|e| e.paths).unwrap_or_default().iter().any(|p| repo_state(&base, p)) {
                let _ = tx.send(());
            }
        })
        .unwrap();
        watcher.watch(&root, RecursiveMode::Recursive).unwrap();
        std::thread::sleep(std::time::Duration::from_millis(300));
        g(&["rm", "-q", "old.tex"]);
        g(&["commit", "-qm", "Remove old"]);
        let seen = rx.recv_timeout(std::time::Duration::from_secs(3)).is_ok();
        let _ = std::fs::remove_dir_all(&dir);
        assert!(seen);
    }
}
